const candidates = $('Find New Registrations').all()
  .map(i => i.json)
  .filter(d => d.domain);

// One item carrying the whole batch: the bulk lookups run once for the list
// instead of once per domain. The API caps a batch at 30 domains.
return [{
  json: {
    domains: candidates.map(d => d.domain).slice(0, 30),
    candidates,
  },
}];

const base = $('Prepare Candidates').first().json.candidates;

const whoisByDomain = new Map();
for (const w of $('Bulk WHOIS').all().map(i => i.json)) {
  if (w.domain) whoisByDomain.set(w.domain, w);
}
const dnsByDomain = new Map();
for (const d of $('Bulk DNS').all().map(i => i.json)) {
  if (d.domain) dnsByDomain.set(d.domain, d);
}

const brand = $('Set Brand').first().json;
const keyword = brand.brand_domain.split('.')[0];

const records = base.map((b) => {
  const w = whoisByDomain.get(b.domain) || {};
  const dns = dnsByDomain.get(b.domain) || {};
  return {
    domain: b.domain,
    registered_date: b.registered_date || '',
    expiry_date: b.expiry_date || '',
    registrar: w.registrar_name || '',
    nameservers: (w.nameservers || dns.nameservers || []).filter(Boolean),
    domain_status: dns.domain_status || '',
  };
});

records.sort((a, b) => (b.registered_date || '').localeCompare(a.registered_date || '') || a.domain.localeCompare(b.domain));

const variantItems = $('Generate Typo Variants').all().map(i => i.json).filter(v => v.domain);
const registeredVariants = variantItems.filter(v => v.registered);
const generatedCount = variantItems[0]?._total ?? registeredVariants.length;

const byType = {};
for (const v of registeredVariants) {
  byType[v.type] = (byType[v.type] || 0) + 1;
}
const forSale = registeredVariants.filter(v => v.status === 'for_sale').map(v => v.domain);
const expiring = registeredVariants.filter(v => v.status === 'expiring').map(v => v.domain);

const lines = records.map(r => {
  const parts = [
    r.domain,
    `  registered ${r.registered_date || 'not reported'}` + (r.expiry_date ? `, expires ${r.expiry_date}` : ''),
    `  registrar: ${r.registrar || 'not reported'}`,
  ];
  parts.push(`  nameservers: ${r.nameservers.length ? r.nameservers.join(', ') : 'none'}`);
  if (r.domain_status) parts.push(`  status: ${r.domain_status}`);
  return parts.join('\n');
});

const body = [
  `Domain data report for ${brand.brand_domain}`,
  'Rolling window: domains registered in the last 10 days',
  '',
  `=== SECTION 1: Registrations containing "${keyword}" ===`,
  '',
  `${records.length} domains, newest first. Empty fields mean the lookup returned nothing.`,
  '',
  records.length ? lines.join('\n\n') : 'No registrations matched the keyword in the last 10 days.',
  '',
  '',
  `=== SECTION 2: Typosquat variants of ${brand.brand_domain} ===`,
  '',
  'Mechanical variants generated from your domain. Independent of section 1: these come from your domain, not from recent registrations.',
  '',
  `${registeredVariants.length} of ${generatedCount} generated variants are registered.`,
  '',
  'By mutation type:',
  Object.entries(byType).sort((a, b) => b[1] - a[1]).map(([t, n]) => `  ${t}: ${n}`).join('\n'),
  '',
  `Listed for sale: ${forSale.length}${forSale.length ? ' (' + forSale.slice(0, 10).join(', ') + (forSale.length > 10 ? ', ...' : '') + ')' : ''}`,
  `Expiring: ${expiring.length}${expiring.length ? ' (' + expiring.slice(0, 10).join(', ') + (expiring.length > 10 ? ', ...' : '') + ')' : ''}`,
  '',
  'Full records are attached as CSV.',
].join('\n');

return [{
  json: {
    subject: `${brand.brand_domain}: ${records.length} registrations in the last 10 days`,
    message: body,
    records,
    variant_summary: {
      generated: generatedCount,
      registered: registeredVariants.length,
      by_type: byType,
      for_sale: forSale,
      expiring: expiring,
    },
  },
}];
